SELECT cd.cd_demo_sk, cd.cd_gender, cd.cd_marital_status, cd.cd_credit_rating, cd.cd_purchase_estimate, SUM(ss.ss_quantity) AS total_sales_quantity, COALESCE(SUM(cr.cr_return_quantity), 0) AS total_return_quantity, SUM(ss.ss_net_profit) AS total_sales_profit, COALESCE(SUM(cr.cr_net_loss), 0) AS total_return_loss, SUM(ss.ss_net_profit) - COALESCE(SUM(cr.cr_net_loss), 0) AS net_gain, DENSE_RANK() OVER (ORDER BY SUM(ss.ss_net_profit) - COALESCE(SUM(cr.cr_net_loss), 0) DESC) AS gain_rank, CASE WHEN cd.cd_purchase_estimate >= 50000 THEN 'Platinum' WHEN cd.cd_purchase_estimate >= 20000 THEN 'Gold' ELSE 'Silver' END AS purchase_tier, CASE WHEN cd.cd_credit_rating IN ('A', 'A+') THEN 'Excellent' ELSE 'Standard' END AS credit_category, ARRAY_AGG(DISTINCT w.w_warehouse_name) AS associated_warehouses FROM customer_demographics cd LEFT JOIN store_sales ss ON ss.ss_cdemo_sk = cd.cd_demo_sk LEFT JOIN catalog_returns cr ON cr.cr_refunded_cdemo_sk = cd.cd_demo_sk LEFT JOIN warehouse w ON cr.cr_warehouse_sk = w.w_warehouse_sk GROUP BY cd.cd_demo_sk, cd.cd_gender, cd.cd_marital_status, cd.cd_credit_rating, cd.cd_purchase_estimate ORDER BY net_gain DESC LIMIT 10
